%% Raincloud plots of MCCAR loadings across four DEP symptom groups
% Required input:
%   DEP_group_loadings.mat generated by extract_DEP_group_loadings.m
%
% Default output:
%   One figure for component 1, containing fMRI, dMRI, and sMRI panels.
%   Change componentsToPlot below to plot additional components.
%
% Each group contains:
%   cloud = kernel-density half violin (all available observations)
%   rain  = jittered individual observations (display subsample only)
%   box   = median, interquartile range, and 1.5-IQR whiskers
%   diamond = arithmetic mean

clearvars;
clc;

%% -------------------------- Configuration -----------------------------
projectRoot = fileparts(mfilename('fullpath'));
inputFile = fullfile(projectRoot, 'DEP_group_loadings.mat');
outputDirectory = fullfile(projectRoot, 'DEP_loading_rainclouds');

% Default: the reference-related first component. Examples:
%   componentsToPlot = [1 2 3];
%   componentsToPlot = 1:80;  % produces 80 separate figures
componentsToPlot = 1;

% These names must follow the order of A{1}, A{2}, A{3}.
modalityNames = ["fMRI", "dMRI", "sMRI"];

groupFieldNames = ["no_or_minimal", "mild", "moderate", "high"];
groupDisplayNames = ["No/minimal", "Mild", "Moderate", "High"];

% Blue-to-red severity palette.
groupColors = [ ...
    0.23, 0.49, 0.72; ...  % no/minimal
    0.55, 0.72, 0.84; ...  % mild
    0.89, 0.55, 0.56; ...  % moderate
    0.70, 0.13, 0.16];     % high

% The density uses all observations. Only the rain points are subsampled
% to avoid covering the figure with thousands of markers.
maxRainPointsPerGroup = 500;
rainPointSize = 9;
rainPointAlpha = 0.22;
cloudAlpha = 0.48;
cloudMaximumWidth = 0.33;
rainMinimumOffset = 0.10;
rainMaximumOffset = 0.34;

% Reproducible display jitter and display-only subsampling.
rng(20261013, 'twister');

%% ----------------------------- Read data ------------------------------
assert(isfile(inputFile), 'Input MAT file does not exist:\n%s', inputFile);
S = load(inputFile, 'DEP');
assert(isfield(S, 'DEP'), 'Variable DEP was not found in:\n%s', inputFile);
DEP = S.DEP;

for g = 1:numel(groupFieldNames)
    fieldName = char(groupFieldNames(g));
    assert(isfield(DEP.groups, fieldName), ...
        'DEP.groups.%s was not found.', fieldName);
end

nModality = numel(DEP.groups.no_or_minimal.loadings);
assert(numel(modalityNames) == nModality, ...
    ['modalityNames contains %d labels, but the DEP structure contains ' ...
     '%d modalities.'], numel(modalityNames), nModality);

nComponent = size(DEP.groups.no_or_minimal.loadings{1}, 2);
assert(all(componentsToPlot >= 1 & componentsToPlot <= nComponent & ...
           componentsToPlot == round(componentsToPlot)), ...
    'componentsToPlot must contain integers between 1 and %d.', nComponent);

if ~isfolder(outputDirectory)
    mkdir(outputDirectory);
end

%% -------------------------- Draw each component -----------------------
for componentNumber = componentsToPlot
    % Extra height is reserved for horizontal x labels and a separate
    % overall title above the modality titles.
    fig = figure('Color', 'w', 'Position', [70, 70, 1500, 650]);

    if exist('tiledlayout', 'file') == 2
        layout = tiledlayout(fig, 1, nModality, ...
            'TileSpacing', 'compact', 'Padding', 'loose');
        if isprop(layout, 'OuterPosition')
            layout.OuterPosition = [0.02, 0.06, 0.96, 0.82];
        end
    else
        layout = [];
    end

    for m = 1:nModality
        if isempty(layout)
            ax = subplot(1, nModality, m, 'Parent', fig);
        else
            ax = nexttile(layout, m);
        end

        hold(ax, 'on');
        groupSizes = zeros(1, numel(groupFieldNames));

        for g = 1:numel(groupFieldNames)
            fieldName = char(groupFieldNames(g));
            values = DEP.groups.(fieldName).loadings{m}(:, componentNumber);
            values = values(isfinite(values));
            groupSizes(g) = numel(values);

            assert(numel(values) >= 2, ...
                'Group %s has fewer than two valid observations.', fieldName);

            drawOneRaincloud(ax, values, g, groupColors(g, :), ...
                maxRainPointsPerGroup, rainPointSize, rainPointAlpha, ...
                cloudAlpha, cloudMaximumWidth, ...
                rainMinimumOffset, rainMaximumOffset);
        end

        % Keep the x-axis clean: show group names only.
        tickLabels = cellstr(groupDisplayNames);

        % Place sample sizes above the rainclouds rather than inside the
        % x-axis labels. Expand the upper y limit to reserve enough space.
        currentYLim = ylim(ax);
        yRange = diff(currentYLim);
        if ~isfinite(yRange) || yRange <= 0
            yRange = 1;
        end
        sampleSizeY = currentYLim(2) + 0.035 * yRange;
        ylim(ax, [currentYLim(1), currentYLim(2) + 0.13 * yRange]);

        for g = 1:numel(groupDisplayNames)
            text(ax, g, sampleSizeY, sprintf('n=%d', groupSizes(g)), ...
                'HorizontalAlignment', 'center', ...
                'VerticalAlignment', 'bottom', ...
                'FontSize', 9, 'FontWeight', 'normal', ...
                'Color', [0.25, 0.25, 0.25], ...
                'Clipping', 'off');
        end

        ax.XLim = [0.5, numel(groupFieldNames) + 0.5];
        ax.XTick = 1:numel(groupFieldNames);
        ax.XTickLabel = tickLabels;
        ax.TickLabelInterpreter = 'none';
        ax.XTickLabelRotation = 0;
        ax.FontSize = 10;
        ax.Layer = 'top';
        grid(ax, 'on');
        ax.XGrid = 'off';
        ax.GridAlpha = 0.15;
        box(ax, 'off');

        xlabel(ax, 'DEP symptom group');
        ylabel(ax, 'MCCAR loading');
        title(ax, modalityNames(m), 'FontWeight', 'bold', 'FontSize', 13);
        hold(ax, 'off');
    end

    figureTitle = sprintf( ...
        'MCCAR component %d loading distributions across DEP groups', ...
        componentNumber);

    % Use an independent annotation instead of title(layout,...) so the
    % overall title cannot overlap the middle modality title.
    annotation(fig, 'textbox', [0.08, 0.925, 0.84, 0.055], ...
        'String', figureTitle, 'EdgeColor', 'none', ...
        'HorizontalAlignment', 'center', ...
        'VerticalAlignment', 'middle', ...
        'FontSize', 15, 'FontWeight', 'bold');

    baseName = sprintf('DEP_raincloud_component_%02d', componentNumber);
    outputPng = fullfile(outputDirectory, [baseName '.png']);
    outputPdf = fullfile(outputDirectory, [baseName '.pdf']);
    outputFig = fullfile(outputDirectory, [baseName '.fig']);

    if exist('exportgraphics', 'file') == 2
        exportgraphics(fig, outputPng, 'Resolution', 300);
        exportgraphics(fig, outputPdf, 'ContentType', 'vector');
    else
        print(fig, outputPng, '-dpng', '-r300');
        print(fig, outputPdf, '-dpdf', '-painters');
    end
    savefig(fig, outputFig);

    fprintf('Saved component %d raincloud figure:\n%s\n', ...
        componentNumber, outputPng);
end

fprintf('\nAll raincloud figures are in:\n%s\n', outputDirectory);

%% --------------------------- Local functions ---------------------------
function drawOneRaincloud(ax, values, position, color, maxRainPoints, ...
        rainPointSize, rainPointAlpha, cloudAlpha, cloudMaximumWidth, ...
        rainMinimumOffset, rainMaximumOffset)

    values = values(:);

    % ---------------- Cloud: left half of a kernel-density violin -------
    if range(values) > 0
        [density, support] = ksdensity(values, 'NumPoints', 200);
        if max(density) > 0
            density = density ./ max(density) .* cloudMaximumWidth;
        end

        cloudX = [position - density, repmat(position, size(density))];
        cloudY = [support, fliplr(support)];
        patch(ax, cloudX, cloudY, color, ...
            'FaceAlpha', cloudAlpha, 'EdgeColor', color, ...
            'LineWidth', 0.8);
    else
        plot(ax, [position - cloudMaximumWidth, position], ...
            [values(1), values(1)], 'Color', color, 'LineWidth', 3);
    end

    % ---------------- Rain: right-side jittered observations ------------
    n = numel(values);
    if n > maxRainPoints
        displayIndex = randperm(n, maxRainPoints);
        displayValues = values(displayIndex);
    else
        displayValues = values;
    end

    jitterX = position + rainMinimumOffset + ...
        (rainMaximumOffset - rainMinimumOffset) .* ...
        rand(size(displayValues));

    scatter(ax, jitterX, displayValues, rainPointSize, color, 'filled', ...
        'MarkerFaceAlpha', rainPointAlpha, ...
        'MarkerEdgeAlpha', rainPointAlpha);

    % ---------------- Box: median, IQR, and Tukey whiskers ---------------
    q1 = prctile(values, 25);
    medianValue = median(values);
    q3 = prctile(values, 75);
    iqrValue = q3 - q1;
    lowerFence = q1 - 1.5 * iqrValue;
    upperFence = q3 + 1.5 * iqrValue;
    lowerWhisker = min(values(values >= lowerFence));
    upperWhisker = max(values(values <= upperFence));

    boxLeft = position - 0.035;
    boxRight = position + 0.070;
    rectangle(ax, 'Position', ...
        [boxLeft, q1, boxRight - boxLeft, max(q3 - q1, eps)], ...
        'FaceColor', [1, 1, 1], ...
        'EdgeColor', [0.15, 0.15, 0.15], 'LineWidth', 1.0);

    plot(ax, [boxLeft, boxRight], [medianValue, medianValue], ...
        'Color', [0.05, 0.05, 0.05], 'LineWidth', 2.0);
    plot(ax, [position, position], [lowerWhisker, q1], ...
        'Color', [0.15, 0.15, 0.15], 'LineWidth', 1.0);
    plot(ax, [position, position], [q3, upperWhisker], ...
        'Color', [0.15, 0.15, 0.15], 'LineWidth', 1.0);
    plot(ax, position, mean(values), 'd', ...
        'MarkerSize', 6, 'MarkerFaceColor', color, ...
        'MarkerEdgeColor', [0.05, 0.05, 0.05], 'LineWidth', 0.8);
end
